import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"AI & LLM Infrastructure — The Free-Tier Architect","description":"API bridges, model routers, agent runtimes and self-hosting — building AI infrastructure that costs nothing to run.","frontmatter":{"title":"AI & LLM Infrastructure — The Free-Tier Architect","description":"API bridges, model routers, agent runtimes and self-hosting — building AI infrastructure that costs nothing to run."},"headers":[],"relativePath":"en/skills/ai-llm/index.md","filePath":"en/skills/ai-llm/index.md"}`),a={name:`en/skills/ai-llm/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="ai-llm-infrastructure-—-the-free-tier-architect" tabindex="-1">AI &amp; LLM Infrastructure — The Free-Tier Architect <a class="header-anchor" href="#ai-llm-infrastructure-—-the-free-tier-architect" aria-label="Permalink to “AI &amp; LLM Infrastructure — The Free-Tier Architect”">​</a></h1><p>Anyone can call a paid API. The interesting engineering is building <strong>infrastructure on free tiers that behaves like a paid one</strong> — and that is precisely what my AI projects do, in layers.</p><h2 id="the-layers" tabindex="-1">The layers <a class="header-anchor" href="#the-layers" aria-label="Permalink to “The layers”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Project</th><th>Job</th></tr></thead><tbody><tr><td>Access</td><td><a href="/Usf/en/projects/glm-free-api/">GLM Free API</a>, <a href="/Usf/en/projects/ghost-brain/">GhostBrain</a>, qwen/deepseek bridges</td><td>Turn free web models into real OpenAI/Anthropic-compatible APIs.</td></tr><tr><td>Routing</td><td><a href="/Usf/en/projects/omnirouter/">OmniRouter</a></td><td>Load balancing, weights, quotas, failover across providers.</td></tr><tr><td>Coordination</td><td><a href="/Usf/en/projects/hermes-stack/">Hermes Stack</a></td><td>Agent runtime + automations + console, self-hosted and free.</td></tr><tr><td>Consumption</td><td><a href="/Usf/en/agentic/overview/">OpenCode · Codex · Claude Code</a></td><td>Agent fleet doing real engineering work through the stack.</td></tr></tbody></table><p>The design rules are consistent: never depend on one provider, never trust a free tier to stay free, always keep an escape hatch. When a bridge dies, the router benches it; when a platform turns hostile, the <a href="/Usf/en/about/networking/">panel discipline</a> applies — migrate in minutes. The result is a multi-model AI stack with a monthly bill of exactly zero.</p><p>On the ML side itself I work with TensorFlow, PyTorch, OpenCV and Hugging Face tooling — enough depth to fine-tune, embed and evaluate, which is usually all a product actually needs.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};